import{c as a,Q as e,j as o,m as l}from"./chunks/framework.DOi4mjdC.js";const s="/assets/PhiloxRandom%E7%A4%BA%E6%84%8F%E5%9B%BE.CBYkjnU4.png",m=JSON.parse('{"title":"PhiloxRandom","description":"","frontmatter":{},"headers":[{"level":1,"title":"PhiloxRandom","slug":"philoxrandom"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/随机函数/PhiloxRandom.md","filePath":"api/SIMD-API/高阶API/随机函数/PhiloxRandom.md"}'),n={name:"api/SIMD-API/高阶API/随机函数/PhiloxRandom.md"};function i(d,t,r,p,h,c){return e(),o("div",null,[...t[0]||(t[0]=[l(`<h1 id="philoxrandom" tabindex="-1">PhiloxRandom <a class="header-anchor" href="#philoxrandom" aria-label="Permalink to &quot;PhiloxRandom&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>x</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>x</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>基于Philox随机数生成算法，给定随机数种子，生成若干的随机数。</p><p>Philox随机数生成的核心算法是一个基于记数的伪随机数生成算法，输入为一个128bit的记数器C，两个32bit的key（k0和k1），输出为4个32bit的整数。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><ul><li><p>连续模式</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;uint16_t Rounds = 7, typename T&gt;</span></span>
<span class="line"><span>__aicore__ inline void PhiloxRandom(const LocalTensor&lt;T&gt;&amp; dstLocal, const PhiloxKey&amp; philoxKey, const PhiloxCounter&amp; philoxCounter, uint16_t count)</span></span></code></pre></div></li><li><p>stride模式</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;uint16_t Rounds = 7, typename T&gt;</span></span>
<span class="line"><span>__aicore__ inline void PhiloxRandom(const LocalTensor&lt;T&gt;&amp; dstLocal, const PhiloxKey&amp; philoxKey, const PhiloxCounter&amp; philoxCounter, const PhiloxRandomParams&amp; params)</span></span></code></pre></div></li></ul><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>Rounds</td><td>Philox算法内部实现迭代次数，支持取值7或10。</td></tr><tr><td>T</td><td>目的操作数数据类型，支持的数据类型为：uint32_t、int32_t、float。 其中uint32_t/int32_t为数据类型范围内的均匀分布，float为0-1范围内的均匀分布。</td></tr></tbody></table><p><strong>表 2</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>dstLocal</td><td>输出</td><td>目的操作数。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 LocalTensor的起始地址需要32字节对齐。</td></tr><tr><td>philoxKey</td><td>输入</td><td>随机数种子。两个32bit的key，定义如下： &lt;pre class=&quot;screen&quot; codetype=&quot;Cpp&quot; id=&quot;screen1284915182119&quot;&gt;using PhiloxKey = uint32_t[2];&lt;/pre&gt;</td></tr><tr><td>philoxCounter</td><td>输入</td><td>随机数种子。一个128bit的记数器C（由4个32bit组成），定义如下： &lt;pre class=&quot;screen&quot; codetype=&quot;Cpp&quot; id=&quot;screen1262844844610&quot;&gt;using PhiloxCounter = uint32_t[4];&lt;/pre&gt;</td></tr><tr><td>count</td><td>输入</td><td>生成目的操作数的元素个数。</td></tr><tr><td>params</td><td>输入</td><td>stride模式计算所需的参数信息。PhiloxRandomParams类型，定义如下： &lt;pre class=&quot;screen&quot; codetype=&quot;Cpp&quot; id=&quot;screen155585184616&quot;&gt;struct PhiloxRandomParams { uint32_t stride; // 两行元素之间的间隔 uint32_t row; // 表示生成的行数 uint32_t column; // 表示生成的每一行的元素个数 }&lt;/pre&gt; row * column大于0，不大于LocalTensor的大小。column % 4 == 0，stride % 4 == 0，stride &gt;= column。</td></tr></tbody></table><p><strong>图 1</strong> PhiloxRandom示意图<br><img src="`+s+`" alt="" title="PhiloxRandom示意图"></p><p>上图是一个生成随机数的示意图。</p><ul><li>连续模式下使用philoxCounter={0, 0, 0, 0}，count=32来生成32个随机数。</li><li>stride模式下可按列分两次生成，调用两次接口。第一次调用参数为philoxCounter={0, 0, 0, 0}，stride=8，row=4，column=4；第二次调用参数为philoxCounter={1, 0, 0, 0}（每次记数器C自增会生成128bit的随机数），stride=8，row=4，column=4。</li></ul><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>无</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>完整算子样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_libraries/11_random/philoxrandom" target="_blank" rel="noreferrer">philoxrandom样例</a>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// dstLocal：存放计算结果的Tensor</span></span>
<span class="line"><span>// philoxKey={0,0}, philoxCounter={0,0,0,0}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// stride模式，生成32*32个元素</span></span>
<span class="line"><span>PhiloxRandom&lt;10&gt;(dstLocal, philoxKey, philoxCounter, params);</span></span>
<span class="line"><span>// 连续模式，生成1024个元素</span></span>
<span class="line"><span>PhiloxRandom&lt;10&gt;(dstLocal, philoxKey, philoxCounter, 1024);</span></span></code></pre></div><p>结果示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[0.31179297 0.8263413  0.6849456 ... 0.10521233 0.29894042 0.96700084]</span></span></code></pre></div>`,25)])])}const x=a(n,[["render",i]]);export{m as __pageData,x as default};
